@Composable
fun AdaptiveScreen() {
    val c = LocalConfiguration.current
    if (c.screenWidthDp >= 600) TwoPaneContent() else SinglePaneContent()
}

class EditViewModel(
    private val savedStateHandle: SavedStateHandle,
    private val repository: DraftRepository
) : ViewModel() {
    val draftId = savedStateHandle.getStateFlow("draftId", "")
    val state = repository.observeDraft(draftId.value)
        .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5_000), EditState())
}

@Composable
fun SearchRoute(viewModel: SearchViewModel = viewModel()) {
    var query by rememberSaveable { mutableStateOf("") }
    val state by viewModel.state.collectAsStateWithLifecycle()
    SearchScreen(query, { query = it }, state)
}

val picker = rememberLauncherForActivityResult(
    ActivityResultContracts.PickVisualMedia()
) { uri -> viewModel.onMediaPicked(uri) }
Button(onClick = { picker.launch(PickVisualMediaRequest()) }) { Text("Chọn ảnh") }
